package com.vit.archds.security; import com.vit.archds.entity.User; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; @Component public class CurrentUserProvider { public User require(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!(a.getPrincipal() instanceof User))throw new IllegalStateException("Authentication required");return (User)a.getPrincipal();}}
